import React, { useState } from "react";
import { useDetectorSocket } from "./useDetectorSocket";
import StatusBar        from "./components/StatusBar";
import CameraFeed       from "./components/CameraFeed";
import AlertPanel       from "./components/AlertPanel";
import StatsPanel       from "./components/StatsPanel";
import AlertToast       from "./components/AlertToast";
import ConfidenceChart  from "./components/ConfidenceChart";
import SettingsPanel    from "./components/SettingsPanel";
import VideoUpload      from "./components/VideoUpload";
import VideoProgressBar from "./components/VideoProgressBar";

const tabBtn = (active) => ({
  padding: "7px 20px", fontSize: 13, fontWeight: active ? 600 : 400,
  cursor: "pointer", borderRadius: 8, border: "0.5px solid #2a2d3a",
  background: active ? "#3b5bdb" : "transparent",
  color: active ? "#fff" : "#6b7280", transition: "all .15s",
});

export default function App() {
  const {
    connected, engineOnline, alerts, latestFrame,
    cameraAlert, videoProgress, videoActive,
  } = useDetectorSocket();

  const [inputMode, setInputMode] = useState("webcam");

  const switchToWebcam = async () => {
    await fetch("http://localhost:3001/use-webcam", { method: "POST" });
    setInputMode("webcam");
  };

  return (
    <div style={{ minHeight: "100vh", background: "#0f1117" }}>

      <StatusBar
        connected={connected}
        engineOnline={engineOnline}
        alertCount={alerts.filter(a => a.type !== "camera_alert").length}
      />

      <div style={{ padding: "20px 24px" }}>

        <StatsPanel alerts={alerts} />

        {/* Input mode toggle */}
        <div style={{
          display: "flex", gap: 8, marginBottom: 16,
          background: "#1a1d27", padding: 6, borderRadius: 10,
          border: "1px solid #2a2d3a", width: "fit-content",
        }}>
          <button style={tabBtn(inputMode === "webcam")}
            onClick={() => { setInputMode("webcam"); switchToWebcam(); }}>
            Webcam
          </button>
          <button style={tabBtn(inputMode === "video")}
            onClick={() => setInputMode("video")}>
            Upload video file
          </button>
        </div>

        {/* Video upload panel */}
        {inputMode === "video" && !videoActive && (
          <VideoUpload
            onVideoStart={(filename) => console.log("Processing:", filename)}
            onVideoStop={() => console.log("Video stopped")}
          />
        )}

        {/* Video progress bar */}
        <VideoProgressBar videoProgress={videoProgress} videoActive={videoActive} />

        <SettingsPanel />

        <ConfidenceChart alerts={alerts} />

        <div style={{ display: "grid", gridTemplateColumns: "1fr 380px", gap: 16 }}>
          <CameraFeed
            latestFrame={latestFrame}
            cameraAlert={cameraAlert}
            engineOnline={engineOnline}
            mode={inputMode}
          />
          <AlertPanel alerts={alerts} />
        </div>

      </div>

      <AlertToast alerts={alerts} />
    </div>
  );
}
